package com.library.ui; import javax.swing.*; import javax.swing.border.*; import java.awt.*; import java.math.BigDecimal;
final class UI { static final Color NAVY=new Color(15,38,71), BLUE=new Color(37,99,235), BG=new Color(244,247,251), GREEN=new Color(22,163,74); private UI(){} static void style(){try{UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());}catch(Exception ignored){} UIManager.put("Label.font",new Font("Segoe UI",Font.PLAIN,14));UIManager.put("Button.font",new Font("Segoe UI",Font.BOLD,13));UIManager.put("TextField.font",new Font("Segoe UI",Font.PLAIN,14));UIManager.put("Table.font",new Font("Segoe UI",Font.PLAIN,14));} static JButton button(String text){JButton b=new JButton(text);b.setUI(new javax.swing.plaf.basic.BasicButtonUI());b.setFont(new Font("Segoe UI",Font.BOLD,14));b.setBackground(BLUE);b.setForeground(Color.WHITE);b.setOpaque(true);b.setContentAreaFilled(true);b.setBorderPainted(false);b.setBorder(new EmptyBorder(10,18,10,18));b.setFocusPainted(false);b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));return b;} static JButton backButton(JFrame frame){JButton b=button("← Back to Dashboard");b.setBackground(Color.WHITE);b.setForeground(NAVY);b.setBorderPainted(true);b.setBorder(new CompoundBorder(new LineBorder(new Color(190,205,225)),new EmptyBorder(9,16,9,16)));b.addActionListener(e->frame.dispose());return b;} static void openAdminPage(JFrame dashboard,JFrame page){page.addWindowListener(new java.awt.event.WindowAdapter(){@Override public void windowClosed(java.awt.event.WindowEvent e){new AdminDashboard().setVisible(true);}});dashboard.dispose();page.setVisible(true);} static JPanel header(JFrame frame,String title,String subtitle){JPanel p=new JPanel(new BorderLayout());p.setBackground(NAVY);p.setBorder(new EmptyBorder(15,22,15,22));JPanel t=new JPanel();t.setOpaque(false);t.setLayout(new BoxLayout(t,BoxLayout.Y_AXIS));JLabel h=new JLabel(title);h.setForeground(Color.WHITE);h.setFont(new Font("Segoe UI",Font.BOLD,22));JLabel s=new JLabel(subtitle);s.setForeground(new Color(203,213,225));s.setFont(new Font("Segoe UI",Font.PLAIN,13));t.add(h);t.add(Box.createVerticalStrut(3));t.add(s);p.add(t,BorderLayout.WEST);p.add(backButton(frame),BorderLayout.EAST);return p;} static void table(JTable t){t.setRowHeight(30);t.setSelectionBackground(new Color(219,234,254));t.setSelectionForeground(NAVY);t.setGridColor(new Color(226,232,240));t.setShowVerticalLines(false);javax.swing.table.JTableHeader h=t.getTableHeader();h.setDefaultRenderer(new javax.swing.table.DefaultTableCellRenderer(){public Component getTableCellRendererComponent(JTable table,Object value,boolean selected,boolean focus,int row,int column){JLabel label=(JLabel)super.getTableCellRendererComponent(table,value,selected,focus,row,column);label.setOpaque(true);label.setBackground(NAVY);label.setForeground(Color.WHITE);label.setFont(new Font("Segoe UI",Font.BOLD,13));label.setBorder(new EmptyBorder(0,10,0,10));return label;}});h.setBackground(NAVY);h.setForeground(Color.WHITE);h.setPreferredSize(new Dimension(1,34));} static JPanel card(String title,String value){JPanel p=new JPanel(new BorderLayout(4,4));p.setPreferredSize(new Dimension(260,118));p.setBackground(Color.WHITE);p.setBorder(new CompoundBorder(new LineBorder(new Color(220,225,232)),new EmptyBorder(14,16,14,16)));JLabel a=new JLabel(title);a.setForeground(Color.DARK_GRAY);JLabel v=new JLabel(value);v.setForeground(NAVY);v.setFont(new Font("Segoe UI",Font.BOLD,24));p.add(a,BorderLayout.NORTH);p.add(v,BorderLayout.CENTER);return p;} static void error(Component c,Exception e){JOptionPane.showMessageDialog(c,e.getMessage(),"Smart Library",JOptionPane.ERROR_MESSAGE);} static void info(Component c,String m){JOptionPane.showMessageDialog(c,m,"Smart Library",JOptionPane.INFORMATION_MESSAGE);} static String rupee(BigDecimal v){return "₹"+v.setScale(2);} }
